fn fast_index(arr: &Vec[Int], idx: Int) -> Int
  requires: idx >= 0;
  requires: idx < arr.len();
{
  return arr[idx];
}

fn main() -> Int {
  // In release with --no-contracts, these checks are removed.
  // Safe IF all callers are trusted.
  let v = Vec[Int]();
  v.push(42);
  return fast_index(&v, 0);
}
